def transform(grid):
    h = len(grid)
    w = len(grid[0])
    # find separator color: color of a fully-uniform row
    sep = None
    for row in grid:
        if all(c == row[0] for c in row):
            sep = row[0]
            break
    out = [row[:] for row in grid]
    for i in range(h):
        if all(c == sep for c in grid[i]):
            out[i] = [2] * w
    for j in range(w):
        if all(grid[i][j] == sep for i in range(h)):
            for i in range(h):
                out[i][j] = 2
    return out
